import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Cross-Site Request Forgery (CSRF)","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/web/cross-site-request-forgery.md","filePath":"d/web/cross-site-request-forgery.md","lastUpdated":1781102819000}`),a={name:`d/web/cross-site-request-forgery.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/web/cross-site-request-forgery.md for this page in Markdown format</div><h1 id="cross-site-request-forgery-csrf" tabindex="-1">Cross-Site Request Forgery (CSRF) <a class="header-anchor" href="#cross-site-request-forgery-csrf" aria-label="Permalink to “Cross-Site Request Forgery (CSRF)”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Cross-site request forgery (CSRF) is a web security vulnerability in which an attacker can unknowingly trick an authenticated user into sending a state-changing HTTP request to the vulnerable web application. In CSRF, an attacker assumes the victim&#39;s identity and access privileges to perform unwanted actions (e.g., change email address) on their behalf. Without appropriate CSRF protection, the web application cannot distinguish between a request prepared by the attacker and a legitimate request from the victim.</p><p>Several prerequisites must be in place for a CSRF attack to take place. First, there must be an action in the web application that is relevant to an attacker and makes sense to exploit. For example, this could be a privileged action, such as changing a user&#39;s access permissions or a password. Another requirement is that no mechanism exists besides cookie-based authentication to distinguish HTTP requests from different users. Suppose the user is authenticated and thus has a valid session cookie. In that case, the web application cannot differentiate between a malicious, subverted request from the attacker and a legitimate request from the victim. Last, ensure that actions do not require specific parameters whose values an attacker cannot determine or predict. For example, if a user is asked to change his password, the function is not vulnerable if an attacker needs to know the value of the existing password.</p><p>A common way to exploit CSRF vulnerabilities is through phishing emails. An attacker does this by preparing malicious links to impose a state-changing request on the victim. The attacker then distributes the malicious links to victims via email. If an authenticated user opens the link in a web browser, the malicious website sends a cross-site request to the vulnerable web application. If successful, the attack causes an action with the victim&#39;s identity and privilege level.</p><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to “Recommendations”">​</a></h2><ul><li>Check if the framework has built-in CSRF protection and use it. If not, ensure that all state-changing requests contain a randomly generated CSRF token with high entropy. Also, validate CSRF tokens properly in the backend.</li><li>Consider various additional security measures: <ul><li>Use Custom Request Headers. By default, the browser&#39;s same-origin policy restricts JavaScript from submitting cross-site requests with custom HTTP request headers.</li><li>Set the <code>SameSite</code> attribute for session cookies to <code>strict</code>. Based on this attribute, web browsers decide whether to include cookies in cross-site requests.</li><li>User interactions such as CAPTCHAs, one-time tokens, re-authentication, etc., can also be considered as additional CSRF protection for highly sensitive actions.</li></ul></li><li>Find detailed information and assistance on preventing CSRF vulnerabilities in the <a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">Cross-Site Request Forgery Cheat Sheet from OWASP</a>.</li></ul>`,8)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};